+RolloutAI.prototype.where=function(){
+    var gameData=this.normalizeGameData(this.gameData)
+
+    if(gameData.edgeCount[gameData.EDGE_NOT]){
+        return this.chooseBestMove(gameData,this.sampleSafeMoves(gameData))
